H.background();
const w = H.W, h = H.H;
const Q = P.Q, Wk = P.W;           // heat added (J), work done BY gas (J)
const dU = Q - Wk;                 // first law: dU = Q - W
// animated phase to show the piston breathing
const ph = (Math.sin(t * 1.2) * 0.5 + 0.5);   // 0..1 oscillation
// piston cylinder on the left
const cx = w * 0.28, cyTop = 110, cylW = 150, cylH = 220;
const pistonMax = 70;
const pistonY = cyTop + 40 + pistonMax * (Wk >= 0 ? ph : (1 - ph)) * H.clamp(Math.abs(Wk) / 200, 0, 1);
H.rect(cx - cylW / 2, cyTop, cylW, cylH, { stroke: H.colors.axis, width: 2 });
H.rect(cx - cylW / 2 + 4, pistonY + 8, cylW - 8, cyTop + cylH - pistonY - 12, { fill: "#1d2c52" });
H.rect(cx - cylW / 2 + 4, pistonY, cylW - 8, 8, { fill: H.colors.violet });
H.text("gas (U)", cx - 26, pistonY + 60, { color: H.colors.sub, size: 12 });
// Heat arrow into the gas from below (Q)
const qy0 = cyTop + cylH + 36, qy1 = cyTop + cylH + 8;
H.arrow(cx, qy0, cx, qy1, { color: Q >= 0 ? H.colors.warn : H.colors.accent, width: 3 });
H.text("Q = " + Q.toFixed(0) + " J", cx + 12, qy0 - 8, { color: H.colors.warn, size: 13 });
// Work arrow on the piston (W done by gas pushes piston up)
H.arrow(cx, pistonY - 6, cx, pistonY - 40, { color: H.colors.good, width: 3 });
H.text("W = " + Wk.toFixed(0) + " J", cx + 12, pistonY - 26, { color: H.colors.good, size: 13 });
// Energy bar chart on the right
const baseX = w * 0.62, baseY = h * 0.62, barW = 46, scale = 0.55;
const bar = (x, val, col, lab) => {
  const hgt = val * scale;
  H.rect(x, baseY - Math.max(0, hgt), barW, Math.abs(hgt), { fill: col });
  if (hgt < 0) H.rect(x, baseY, barW, -hgt, { fill: col });
  H.text(lab, x + 2, baseY + 18, { color: H.colors.sub, size: 12 });
};
H.line(baseX - 20, baseY, w - 30, baseY, { color: H.colors.axis, width: 1.5 });
bar(baseX, Q, H.colors.warn, "Q");
bar(baseX + 70, Wk, H.colors.good, "W");
bar(baseX + 140, dU, H.colors.accent, "ΔU");
H.text("First law: ΔU = Q − W", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Q = " + Q.toFixed(0) + " J   W = " + Wk.toFixed(0) + " J   →   ΔU = " + dU.toFixed(0) + " J", 24, 54, { color: H.colors.sub, size: 13 });
H.legend([{ label: "Q heat in", color: H.colors.warn }, { label: "W work by gas", color: H.colors.good }, { label: "ΔU internal", color: H.colors.accent }], w - 200, 90);
